arguments.file_text:
@page "/dashboard"
@inject Services.WarehouseState WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-header">
                <h5 class="mb-0">Current Warehouse</h5>
            </div>
            <div class="card-body">
                <p class="card-text fs-4">@WarehouseState.SelectedWarehouseName</p>
                <p class="text-muted">ID: @WarehouseState.SelectedWarehouseId</p>
            </div>
        </div>
    </div>

    <div class="col-md-6">
        <div class="card @(AlertService.LowStockCount > 5 ? "border-danger" : "border-success")">
            <div class="card-header d-flex justify-content-between align-items-center">
                <h5 class="mb-0">Low Stock Alerts</h5>
                <span class="badge @(AlertService.LowStockCount > 5 ? "bg-danger" : "bg-success") fs-6">
                    @AlertService.LowStockCount
                </span>
            </div>
            <div class="card-body">
                @if (AlertService.LowStockCount > 5)
                {
                    <p class="text-danger fw-bold">
                        ⚠️ @AlertService.LowStockCount items are below minimum stock levels!
                    </p>
                }
                else if (AlertService.LowStockCount > 0)
                {
                    <p class="text-warning">
                        @AlertService.LowStockCount items need attention.
                    </p>
                }
                else
                {
                    <p class="text-success">✅ All items are adequately stocked.</p>
                }
                <p class="text-muted small mb-0">Refreshes every 10 seconds. Last check: @_lastRefresh.ToString("HH:mm:ss")</p>
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;
    private DateTime _lastRefresh = DateTime.Now;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(() =>
        {
            _lastRefresh = DateTime.Now;
            StateHasChanged();
        });
        _warehouseHandler = () => InvokeAsync(StateHasChanged);

        AlertService.OnAlertCountChanged += _alertHandler;
        WarehouseState.OnChange += _warehouseHandler;

        // Start polling when the dashboard is visible
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        // Stop polling when user leaves this page
        AlertService.StopPolling();

        if (_alertHandler is not null)
            AlertService.OnAlertCountChanged -= _alertHandler;
        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
    }
}

